1	/**
2	 * Traceback rendering for the frozen `test4` script.
3	 *
4	 * The reference build is a PyInstaller bundle, so an unhandled exception prints
5	 * a CPython traceback whose frames point at the original `test4.py` source
6	 * lines, followed by PyInstaller's own one-line summary.  Frames inside the
7	 * bundled `bech32` package have no source text available, so only their
8	 * location lines appear.
9	 */
10	
11	import { writeStderr } from './stdio.mjs';
12	
13	const SCRIPT_MODULE = 'test4';
14	const SCRIPT_FILE = 'test4.py';
15	const LIBRARY_FILE = 'bech32/__init__.py';
16	
17	const MODULE_FRAME = {
18	  file: SCRIPT_FILE,
19	  line: 16,
20	  name: '<module>',
21	  source: 'main()',
22	};
23	
24	/** Frames for a failure inside `witprog = list(map(int, args.c.split(',')))`. */
25	export const CONVERT_ARGUMENT_FRAMES = [
26	  MODULE_FRAME,
27	  {
28	    file: SCRIPT_FILE,
29	    line: 11,
30	    name: 'main',
31	    source: "witprog = list(map(int, args.c.split(',')))",
32	    anchorStart: 'witprog = '.length,
33	  },
34	];
35	
36	/** Frames for a failure raised out of `bech32.encode(...)`. */
37	export const ENCODE_FRAMES = [
38	  MODULE_FRAME,
39	  {
40	    file: SCRIPT_FILE,
41	    line: 12,
42	    name: 'main',
43	    source:
44	      'result = bech32.encode(args.a, args.b, witprog)  # Encode segwit address',
45	    anchorStart: 'result = '.length,
46	    // The anchor covers the call only, not the trailing comment.
47	    anchorEnd: 'result = bech32.encode(args.a, args.b, witprog)'.length,
48	  },
49	  { file: LIBRARY_FILE, line: 127, name: 'encode' },
50	  { file: LIBRARY_FILE, line: 61, name: 'bech32_encode' },
51	];
52	
53	function frameLines(frame) {
54	  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.name}`];
55	  if (frame.source === undefined) return lines;
56	  lines.push(`    ${frame.source}`);
57	  if (frame.anchorStart !== undefined) {
58	    const end = frame.anchorEnd ?? frame.source.length;
59	    lines.push(
60	      `    ${' '.repeat(frame.anchorStart)}${'^'.repeat(end - frame.anchorStart)}`,
61	    );
62	  }
63	  return lines;
64	}
65	
66	/**
67	 * Prints the traceback for an unhandled exception exactly as the frozen build
68	 * does, including PyInstaller's trailing failure notice.
69	 */
70	export function reportUnhandledException(error, frames) {
71	  const lines = ['Traceback (most recent call last):'];
72	  for (const frame of frames) lines.push(...frameLines(frame));
73	  lines.push(`${error.typeName}: ${error.pythonMessage}`);
74	  lines.push(
75	    `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_MODULE}' due to unhandled exception!`,
76	  );
77	  writeStderr(`${lines.join('\n')}\n`);
78	}
